    FOREIGN KEY (userid) REFERENCES "Users"(userid) ON DELETE CASCADE
);
CREATE TABLE "SharedEpisodes" (
    sharedepisodeid INTEGER PRIMARY KEY AUTOINCREMENT,
    episodeid INTEGER NOT NULL,
    sharedby INTEGER NOT NULL,
    sharedwith INTEGER,
    sharecode TEXT,
    expirationdate TIMESTAMP,
    FOREIGN KEY (episodeid) REFERENCES "Episodes"(episodeid) ON DELETE CASCADE,
    FOREIGN KEY (sharedby) REFERENCES "Users"(userid) ON DELETE CASCADE,
    FOREIGN KEY (sharedwith) REFERENCES "Users"(userid) ON DELETE CASCADE,
    UNIQUE (sharecode)
);
CREATE TABLE "SyncImportFailures" (
    failureid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER NOT NULL,
    feedurl TEXT NOT NULL,
    origin TEXT NOT NULL,
    errorkind TEXT NOT NULL,
    lasterror TEXT,
    attempts INTEGER NOT NULL DEFAULT 1,
    firstfailedat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lastattemptat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    nextattemptat TIMESTAMP,
    FOREIGN KEY (userid) REFERENCES "Users"(userid) ON DELETE CASCADE,
    UNIQUE (userid, feedurl)
);
CREATE TABLE "SyncTargets" (
    targetid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER NOT NULL,
    kind TEXT NOT NULL,
    url TEXT NOT NULL,
    username TEXT NOT NULL DEFAULT '',
    encryptedsecret TEXT NOT NULL,
    devicename TEXT,
    enabled BOOLEAN NOT NULL DEFAULT 1,
    subspullcursor BIGINT NOT NULL DEFAULT 0,
    actionspullcursor BIGINT NOT NULL DEFAULT 0,
    subspushcursor BIGINT NOT NULL DEFAULT 0,
    actionspushcursor BIGINT NOT NULL DEFAULT 0,
    needsfullsync BOOLEAN NOT NULL DEFAULT 1,
    lastattemptat TIMESTAMP,
    lastsuccessat TIMESTAMP,
    lasterror TEXT,
    consecutivefailures INTEGER NOT NULL DEFAULT 0,
    createdat TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (((kind) IN ('gpodder', 'nextcloud'))),
    FOREIGN KEY (userid) REFERENCES "Users"(userid) ON DELETE CASCADE,
    UNIQUE (userid)
);
CREATE TABLE "UserEpisodeHistory" (
    userepisodehistoryid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER,
    episodeid INTEGER,
    listendate TIMESTAMP,
    listenduration INTEGER,
    FOREIGN KEY (episodeid) REFERENCES "Episodes"(episodeid),
    FOREIGN KEY (userid) REFERENCES "Users"(userid),
    UNIQUE (userid, episodeid)
);
CREATE TABLE "UserEpisodeState" (
    userid INTEGER NOT NULL,
    episodeid INTEGER NOT NULL,
    completed BOOLEAN NOT NULL DEFAULT 0,
    completedat TIMESTAMP,
    PRIMARY KEY (userid, episodeid),
    FOREIGN KEY (episodeid) REFERENCES "Episodes"(episodeid) ON DELETE CASCADE,
    FOREIGN KEY (userid) REFERENCES "Users"(userid) ON DELETE CASCADE
);
CREATE TABLE "UserNotificationSettings" (
    settingid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER,
    platform TEXT NOT NULL,
    enabled BOOLEAN DEFAULT 1,
    ntfytopic TEXT,
    ntfyserverurl TEXT DEFAULT 'https://ntfy.sh',
    gotifyurl TEXT,
    gotifytoken TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    ntfyusername TEXT,
    ntfypassword TEXT,
    ntfyaccesstoken TEXT,
    httpurl TEXT,
    httptoken TEXT,
    httpmethod TEXT DEFAULT 'POST',
    FOREIGN KEY (userid) REFERENCES "Users"(userid) ON DELETE CASCADE,
    UNIQUE (userid, platform)
);
CREATE TABLE "UserSettings" (
    usersettingid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER,
    theme TEXT DEFAULT 'Nordic',
    startpage TEXT DEFAULT 'home',
    autocompleteseconds INTEGER DEFAULT 0,
    collection_add_ui TEXT DEFAULT 'modal',
    FOREIGN KEY (userid) REFERENCES "Users"(userid),
    UNIQUE (userid)
);
CREATE TABLE "UserStats" (
    userstatsid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER,
    usercreated TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    podcastsplayed INTEGER DEFAULT 0,
    timelistened INTEGER DEFAULT 0,
    podcastsadded INTEGER DEFAULT 0,
    episodessaved INTEGER DEFAULT 0,
    episodesdownloaded INTEGER DEFAULT 0,
    FOREIGN KEY (userid) REFERENCES "Users"(userid),
    UNIQUE (userid)
);
CREATE TABLE "UserVideoHistory" (
    uservideohistoryid INTEGER PRIMARY KEY AUTOINCREMENT,
    userid INTEGER,
    videoid INTEGER,
    listendate TIMESTAMP,
    listenduration INTEGER DEFAULT 0,
    FOREIGN KEY (userid) REFERENCES "Users"(userid),
    FOREIGN KEY (videoid) REFERENCES "YouTubeVideos"(videoid),
    UNIQUE (userid, videoid)
);
CREATE TABLE "Users" (
    userid INTEGER PRIMARY KEY AUTOINCREMENT,
    fullname TEXT,
    username TEXT,
    email TEXT,
    hashed_pw TEXT,
    isadmin BOOLEAN,
    reset_code TEXT,
    reset_expiry TIMESTAMP,
    mfa_secret TEXT,
    timezone TEXT DEFAULT 'UTC',
    timeformat INTEGER DEFAULT 24,
    dateformat TEXT DEFAULT 'ISO',
    firstlogin BOOLEAN DEFAULT 0,
    gpodderurl TEXT DEFAULT '',
    pod_sync_type TEXT DEFAULT 'None',
    gpodderloginname TEXT DEFAULT '',
    gpoddertoken TEXT DEFAULT '',
    enablerssfeeds BOOLEAN DEFAULT 0,
    auth_type TEXT DEFAULT 'standard',
    oidc_provider_id INTEGER,
    oidc_subject TEXT,
    playbackspeed REAL DEFAULT 1.0,
    autodownloaddeletedays INTEGER DEFAULT 0,
    defaultvolume INTEGER DEFAULT 100,
    gpodderserverenabled BOOLEAN NOT NULL DEFAULT 0,
    syncnotice TEXT,
    lastsynctime TIMESTAMP,
    defaultgpodderdevice TEXT,
    language TEXT DEFAULT 'en',
    usepodcastcovers BOOLEAN DEFAULT 0,
    autodeleteoncomplete BOOLEAN DEFAULT 0,
    usegravatar BOOLEAN NOT NULL DEFAULT 0,
    FOREIGN KEY (oidc_provider_id) REFERENCES "OIDCProviders"(providerid),
    UNIQUE (username)
);
CREATE TABLE "YouTubeVideos" (
    videoid INTEGER PRIMARY KEY AUTOINCREMENT,
    podcastid INTEGER,
    videotitle TEXT,
    videodescription TEXT,
    videourl TEXT,
    thumbnailurl TEXT,
    publishedat TIMESTAMP,
    duration INTEGER,
    youtubevideoid TEXT,
    completed BOOLEAN DEFAULT 0,
    listenposition INTEGER DEFAULT 0,
    FOREIGN KEY (podcastid) REFERENCES "Podcasts"(podcastid)
);

